package com.crowdsafety.service;
import com.crowdsafety.model.*; import com.crowdsafety.repo.*; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.*; import org.springframework.stereotype.Service; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException;
import java.time.*; import java.util.*;
@Service public class CrowdService {
 private final PlaceRepository places; private final CrowdObservationRepository observations; private final PredictionRepository predictions; private final ObjectMapper mapper;
 public CrowdService(PlaceRepository p,CrowdObservationRepository o,PredictionRepository pr,ObjectMapper m){places=p;observations=o;predictions=pr;mapper=m;}
 public List<JsonNode> allPlaces(String search,String category,String city){return places.findAll().stream().map(p -> (JsonNode) json(p)).filter(p->category.isBlank()||category.equalsIgnoreCase("All")||p.path("category").asText().equalsIgnoreCase(category)).filter(p->city.isBlank()||city.equalsIgnoreCase("All")||p.path("city").asText().equalsIgnoreCase(city)).filter(p->search.isBlank()||(p.path("name").asText()+" "+p.path("city").asText()+" "+p.path("category").asText()+" "+p.path("description").asText()).toLowerCase().contains(search.toLowerCase())).toList();}
 public JsonNode place(String id){return json(find(id));}
 private PlaceEntity find(String id){return places.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Place not found: "+id));}
 private ObjectNode json(PlaceEntity p){try{return (ObjectNode)mapper.readTree(p.getPlaceJson());}catch(Exception e){throw new IllegalStateException(e);}}
 private ObjectNode level(int index){int n=Math.max(0,Math.min(100,index));String key,label,shortLabel,hex,desc;if(n<=39){key="low";label="Low Crowd";shortLabel="Low";hex="#22C55E";desc="Minimal wait times and ample personal space expected.";}else if(n<=69){key="moderate";label="Moderate Crowd";shortLabel="Moderate";hex="#F59E0B";desc="Steady visitor flow with typical entry delays.";}else{key="high";label="High Crowd";shortLabel="High";hex="#EF4444";desc="Dense crowding, extended queues, and peak congestion anticipated.";}ObjectNode x=mapper.createObjectNode();x.put("min",key.equals("low")?0:key.equals("moderate")?40:70);x.put("max",key.equals("low")?39:key.equals("moderate")?69:100);x.put("key",key);x.put("label",label);x.put("shortLabel",shortLabel);x.put("hex",hex);x.put("description",desc);x.put("index",n);return x;}
 private String fmt(int h){int a=h%24;return (a%12==0?12:a%12)+":00 "+(a<12?"AM":"PM");}
 public ObjectNode predict(String id,String date,String time){PlaceEntity p=find(id);JsonNode place=json(p);LocalDate d=LocalDate.parse(date);LocalTime t=LocalTime.parse(time);int hour=t.getHour();boolean weekend=d.getDayOfWeek()==DayOfWeek.SATURDAY||d.getDayOfWeek()==DayOfWeek.SUNDAY;String day=weekend?"WEEKEND":"WEEKDAY";List<CrowdObservation> obs=observations.findByPlace_IdAndDayType(id,day);int base=obs.stream().filter(o->o.getHour()==hour).mapToInt(CrowdObservation::getCrowdIndex).findFirst().orElse(0);int hash=date.chars().sum();int variance=(hash%9)-4;int index=Math.max(2,Math.min(99,base+variance));ObjectNode result=mapper.createObjectNode();result.put("placeId",id);result.put("placeName",place.path("name").asText());result.put("category",place.path("category").asText());result.put("city",place.path("city").asText());result.put("description",place.path("description").asText());result.set("image",place.path("image"));result.put("date",date);result.put("time",fmt(hour));result.put("targetHour",hour);result.put("isWeekend",weekend);result.put("index",index);result.put("level",level(index).path("key").asText());result.set("levelConfig",level(index));result.put("confidence",place.path("category").asText().equals("Public Event")||place.path("waitingTime").isNull()?"Medium":"High");result.put("explanation",weekend?"Historical sample weekend patterns indicate higher visitor activity for this place.":"Estimated from the sample weekday crowd pattern for this place.");result.set("waitingTime",place.path("waitingTime"));result.set("safetyStatus",place.path("safetyStatus"));result.set("emergencyContacts",place.path("emergencyContacts"));result.set("accessibilityInfo",place.path("accessibilityInfo"));result.set("verifiedIncidents",place.path("verifiedIncidents"));result.set("notices",place.path("notices"));
  ArrayNode hourly=mapper.createArrayNode();int[] curve=new int[24];for(int h=0;h<24;h++){final int hh=h;int v=Math.max(0,Math.min(100,obs.stream().filter(o->o.getHour()==hh).mapToInt(CrowdObservation::getCrowdIndex).findFirst().orElse(0)+(int)Math.round(variance*.7)));curve[h]=v;ObjectNode item=mapper.createObjectNode();item.put("hour",h);item.put("displayHour",fmt(h));item.put("shortHour",h==0?"12A":h<12?h+"A":h==12?"12P":(h-12)+"P");item.put("index",v);item.put("level",level(v).path("key").asText());item.put("levelLabel",level(v).path("label").asText());item.put("hex",level(v).path("hex").asText());item.put("isSelected",h==hour);hourly.add(item);}result.set("hourlyData",hourly);
  int busy=8,quiet=7,bmax=-1,qmin=999;for(int h=7;h<=20;h++){int sum=curve[h]+curve[h+1]+curve[h+2];if(h>=8&&sum>bmax){bmax=sum;busy=h;}if(sum<qmin){qmin=sum;quiet=h;}}result.put("busiestPeriod",fmt(busy)+" - "+fmt(busy+3)+" (Avg index: "+Math.round(bmax/3.0)+")");result.put("quietestPeriod",fmt(quiet)+" - "+fmt(quiet+3)+" (Avg index: "+Math.round(qmin/3.0)+")");
  if(index>=70||List.of("caution","alert").contains(place.path("safetyStatus").asText())){int sh=7;for(int h=7;h<=18;h++)if(curve[h]<45){sh=h;break;}int si=curve[sh];int diff=Math.max(15,Math.round((index-si)*100f/index));ObjectNode better=mapper.createObjectNode();better.put("suggestedTime",fmt(sh));better.put("suggestedDay",weekend?"Weekday Morning":"Earlier in the day");better.put("predictedIndex",si);better.put("reductionPercent",diff);better.put("reason","Sample crowd index is lower at the suggested time; this is an estimate, not a guarantee.");result.set("betterTime",better);}else result.putNull("betterTime");
  ArrayNode alternatives=mapper.createArrayNode();for(PlaceEntity alt:places.findAll()){if(alt.getId().equals(id)||alternatives.size()>=3)continue;JsonNode a=json(alt);int ai=a.path(weekend?"hourlyWeekend":"hourlyWeekday").get(hour).asInt();ObjectNode item=mapper.createObjectNode();item.put("id",alt.getId());item.put("name",alt.getName());item.put("category",alt.getCategory());item.put("city",alt.getCity());item.set("image",a.path("image"));item.put("predictedIndex",ai);item.put("predictedLevel",level(ai).path("key").asText());item.put("predictedLevelLabel",level(ai).path("label").asText());item.set("safetyStatus",a.path("safetyStatus"));item.set("waitingTime",a.path("waitingTime"));item.put("reason","Illustrative alternative based on the sample crowd index.");alternatives.add(item);}result.set("alternatives",alternatives);
  String risk=index>=70?"ELEVATED":index>=40?"MODERATE":"LOWER";predictions.save(new PredictionRecord(id,d,t,result.path("level").asText(),risk,index));return result;
 }
 public List<JsonNode> notices(String placeId,String type,String severity){List<JsonNode> out=new ArrayList<>();for(PlaceEntity p:places.findAll()){if(!placeId.isBlank()&&!placeId.equals("All")&&!placeId.equals(p.getId()))continue;JsonNode place=json(p);for(JsonNode n:place.path("notices")){if(!type.isBlank()&&!type.equals("All")&&!type.equalsIgnoreCase(n.path("type").asText()))continue;if(!severity.isBlank()&&!severity.equals("All")&&!severity.equalsIgnoreCase(n.path("severity").asText()))continue;ObjectNode x=((ObjectNode)n.deepCopy());x.put("placeId",p.getId());x.put("placeName",p.getName());x.put("category",p.getCategory());x.put("city",p.getCity());x.set("placeSafetyStatus",place.path("safetyStatus"));x.set("emergencyContacts",place.path("emergencyContacts"));x.set("accessibilityInfo",place.path("accessibilityInfo"));x.set("verifiedIncidents",place.path("verifiedIncidents"));out.add(x);}}return out;}
 public ObjectNode heatmap(String id){PlaceEntity p=find(id);JsonNode place=json(p);ObjectNode out=mapper.createObjectNode();out.put("placeId",id);out.put("placeName",p.getName());out.put("category",p.getCategory());out.put("city",p.getCity());out.set("typicalCrowdLevel",place.path("typicalCrowdLevel"));out.set("typicalCrowdIndex",place.path("typicalCrowdIndex"));ArrayNode matrix=mapper.createArrayNode();String[] days={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};for(int d=0;d<7;d++){boolean wk=d>=5;JsonNode curve=place.path(wk?"hourlyWeekend":"hourlyWeekday");ObjectNode day=mapper.createObjectNode();day.put("day",days[d]);day.put("isWeekend",wk);ArrayNode hours=mapper.createArrayNode();for(int h=0;h<24;h++){int val=Math.max(0,Math.min(100,curve.get(h).asInt()+(d==4?4:d==0?-3:0)));ObjectNode hr=mapper.createObjectNode();hr.put("hour",h);hr.put("displayHour",fmt(h));hr.put("index",val);hr.put("level",level(val).path("key").asText());hr.put("hex",level(val).path("hex").asText());hours.add(hr);}day.set("hours",hours);matrix.add(day);}out.set("matrix",matrix);return out;}
 public List<String> cities(){return places.findAll().stream().map(PlaceEntity::getCity).distinct().sorted().toList();}
 public List<String> categories(){return places.findAll().stream().map(PlaceEntity::getCategory).distinct().sorted().toList();}
}
